static void JOY1_EXTI_Callback(void)
{
  uint32_t it_status;
  JOYPin_TypeDef JoyPin = JOY_NONE;
#if (USE_BSP_IO_CLASS > 0)
  it_status = (uint32_t)BSP_IO_GetIT(0, JOY_ALL);
#endif
  switch(it_status)
  {
  case JOY_SEL:
    JoyPin = JOY_SEL;
    break;
  case JOY_DOWN:
    JoyPin = JOY_DOWN;
    break;
  case JOY_LEFT:
    JoyPin = JOY_LEFT;
    break;
  case JOY_RIGHT:
    JoyPin = JOY_RIGHT;
    break;
  case JOY_UP:
    JoyPin = JOY_UP;
    break;
  default:
    break;
  }

  BSP_JOY_Callback(JOY1, JoyPin);
#if (USE_BSP_IO_CLASS > 0)
  (void)BSP_IO_ClearIT(0, it_status);
#endif
}
