  */
#define STM32H743I_EVAL_BSP_VERSION_MAIN   (0x03) /*!< [31:24] main version   */
#define STM32H743I_EVAL_BSP_VERSION_SUB1   (0x03) /*!< [23:16] sub1 version   */
#define STM32H743I_EVAL_BSP_VERSION_SUB2   (0x03) /*!< [15:8]  sub2 version   */
